raw:
{
  "spells": [
    {
      "id": "spell_water_07",
      "theory": "水绳术让魔力沿水流内部的细脉游走，使一段活水暂时维持束状而不散开。需要足量流动或静止的水作为媒介，水量不足时只能形成松垮水带。缠绕一肢时，水流会贴合肢体轮廓，但可被利器或强力水流切断，媒介一断束缚即解。",
      "casting": "双手浸入水中，以指节在水下画连续螺旋，同时念出短促音节引导魔力沿螺旋收紧。待水线成形后，将手腕向目标方向轻甩。",
      "failure": "水流可能突然散落，淋湿施术者衣袖和地面，或只缠住片刻便滑脱。若魔力输入过猛，水绳会短暂变硬后炸开，发出闷响并溅起水花。",
      "counters": [
        "用刀剑横切水绳中段，媒介断开后束缚立即失效。",
        "以另一股强水流冲击水绳连接处，可将其冲散。"
      ],
      "socialConsequences": "渡口船工用它固定漂散的货物，乡约也允许在纠纷中暂时约束动手者。被缠住的人常感到受辱，事后可能向乡约申诉要求道歉。商队护卫担心水绳被用来劫货，会要求同伴远离可疑水边。公开表演水绳缠人而不说明用途，容易引起围观者不安。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时水绳粗细不均，可能中途滑脱。",
        "稳定输入后，水绳能更准确地缠住指定的一肢。",
        "熟练者控制收紧程度，减少对肢体的擦伤。",
        "高熟练度下成形更快，仍只限一肢与足量水。"
      ]
    },
    {
      "id": "spell_water_08",
      "theory": "霜针术把魔力压入一小团水汽，使其在指尖前方凝成短冰针。冰针靠寒气维持，在炎热环境中会变钝变短，甚至未及命中便融为水滴。冰针飞行轨迹较直，可被盾牌或厚衣挡下，命中后只造成短时刺痛和局部冻伤。",
      "casting": "掌心向上虚托，食指与中指并拢向前一推，同时以齿音短喝。水汽从掌心聚成白点，随即拉长为针。",
      "failure": "冰针可能在掌心碎裂，冻伤施术者指节，或飞出后偏斜扎入地面。炎热时冰针会提前融化，只剩一滴冷水落在目标脚边。",
      "counters": [
        "举起木盾或厚皮革，冰针会钉在表面并迅速融化。",
        "以干燥热风提前吹散掌心水汽，使冰针无法凝成。"
      ],
      "socialConsequences": "码头卸货工在争执中动用霜针，会被港务视作伤人并追究货损连带责任。城中公会要求登记冰针的练习用途，防止在集市误伤行人。炎热季节里冰针威力下降，商贩反而乐意请人用其冷却少量饮品。被冰针擦伤的学徒可能向师傅抱怨，影响其在行会中的口碑。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "低熟练度时冰针常偏斜，只能擦过目标。",
        "熟练后冰针飞行更直，能稳定命中近处目标。",
        "控制寒气集中，减少对周围人或物的冻伤。",
        "高熟练度下冰针成形更快，仍受炎热削弱。"
      ]
    },
    {
      "id": "spell_water_09",
      "theory": "河床听辨将魔力送入水中，借回波测出小段水道的浅滩位置与流速变化。施术者需投入一小块树脂作为媒介，树脂在水中溶散时把回声传回掌心。它只能感知约二十米内的一段河床，无法预测整条河的流向或远方水情。",
      "casting": "蹲在岸边，将树脂块按入浅水，掌心贴水面感受回波。闭眼默数三次呼吸，再沿水流方向缓缓移动手掌。",
      "failure": "树脂可能未溶散便沉底，回波杂乱，使施术者误判浅滩位置。若水流过急，掌心会被冲离水面，只感到一片模糊的震动，无法分辨流速。",
      "counters": [
        "在上游投放泥沙搅浑水流，回波会被杂音掩盖。",
        "用石板隔断水面，掌心无法接触水层，感知即中断。"
      ],
      "socialConsequences": "船夫依赖它避开暗滩，乡约允许在公共河段使用，但要求不得惊扰鱼群产卵区。渔户担心频繁施术会吓跑鱼群，可能要求施术者改到下游。渡口管事乐意雇人测浅滩，却不愿承担因误判导致的搁浅赔偿。若在他人承包的养殖水段使用，须先取得承包人同意。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "低熟练度时回波模糊，浅滩位置常有偏差。",
        "熟练者能区分浅滩与深槽，减少误判。",
        "控制掌心角度后，流速读数更稳定可靠。",
        "高熟练度下感知更快，仍限于小段水道。"
      ]
    }
  ]
}
